CREATE VIEW [dbo].[StatoApparecchi] AS SELECT 'NSL' AS Categoria, 'New Slot' AS Tipo, 2 AS TipoOggetto, 'NSL' AS TipoOggettoDesc, IdDedicato AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, nome AS Modello, identificativo, nullaosta, 1 AS TM, NonAttivo AS Attivo, IdMagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria From dedicati Where DataFine Is Null And ParTipologiaMonopoli = 1 Union SELECT 'C7A' AS Categoria, 'Gioco' AS Tipo, 2 AS TipoOggetto, 'GIO' AS TipoOggettoDesc, IdDedicato AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, nome AS Modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, NonAttivo AS Attivo, IdMagazzino, 1 AS Ordinamento, 1 AS OrdinamentoCategoria From dedicati Where DataFine Is Null And ParTipologiaMonopoli = 2 Union SELECT 'C7C' AS Categoria, 'Gioco' AS Tipo, 2 AS TipoOggetto, 'GIO' AS TipoOggettoDesc, iddedicato AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, nome AS Modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, NonAttivo AS Attivo, IdMagazzino, 1 AS Ordinamento, 2 AS OrdinamentoCategoria From dedicati Where DataFine Is Null And ParTipologiaMonopoli = 4 Union SELECT 'MEC' AS Categoria, 'Gioco' AS Tipo, 2 AS TipoOggetto, 'GIO' AS TipoOggettoDesc, iddedicato AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, nome AS Modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, NonAttivo AS Attivo, IdMagazzino, 1 AS Ordinamento, 3 AS OrdinamentoCategoria From dedicati WHERE DataFine IS NULL AND (partipologiamonopoli > 4 OR partipologiamonopoli IS NULL) Union SELECT 'NSL' AS Categoria, 'Mobile' AS Tipo, 0 AS TipoOggetto, 'MOB' AS TipoOggettoDesc, idmobile AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, Attivo, IdMagazzino, 2 AS Ordinamento, 0 AS OrdinamentoCategoria From mobili Where DataFine Is Null And ParTipologiaMonopoli = 1 Union SELECT 'C7A' AS Categoria, 'Mobile' AS Tipo, 0 AS TipoOggetto, 'MOB' AS TipoOggettoDesc, idmobile AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, Attivo, IdMagazzino, 2 AS Ordinamento, 1 AS OrdinamentoCategoria From mobili Where DataFine Is Null And ParTipologiaMonopoli = 2 Union SELECT 'C7C' AS Categoria, 'Mobile' AS Tipo, 0 AS TipoOggetto, 'MOB' AS TipoOggettoDesc, idmobile AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, Attivo, IdMagazzino, 2 AS Ordinamento, 2 AS OrdinamentoCategoria From mobili Where DataFine Is Null And ParTipologiaMonopoli = 4 Union SELECT 'MEC' AS Categoria, 'Mobile' AS Tipo, 0 AS TipoOggetto, 'MOB' AS TipoOggettoDesc, idmobile AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, modello, identificativo, nullaosta, ParTipologiaMonopoli AS TM, Attivo, IdMagazzino, 2 AS Ordinamento, 3 AS OrdinamentoCategoria From mobili WHERE DataFine IS NULL AND (partipologiamonopoli > 4 OR partipologiamonopoli IS NULL) Union SELECT 'SCH' AS Categoria, 'Scheda' AS Tipo, 1 AS TipoOggetto, 'SCH' AS TipoOggettoDesc, idscheda AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, nome AS Modello, '' AS identificativo, '' AS nullaosta, NULL AS TM, Attivo, IdMagazzino, 3 AS Ordinamento, 4 AS OrdinamentoCategoria From schede Where DataFine Is Null Union SELECT 'DIS' AS Categoria, 'Distributore' AS Tipo, 15 AS TipoOggetto, 'DIS' AS TipoOggettoDesc, iddistributore AS CodiceOggetto, prop AS Proprieta, agente AS Associato, matricola, nome AS Modello, '' AS identificativo, '' AS nullaosta, NULL AS TM, Attivo, IdMagazzino, 4 AS Ordinamento, 5 AS OrdinamentoCategoria From distribut Where DataFine Is Null
